import styled from "styled-components";

export const HeaderContainer = styled.header`
    width: 100%;
    display: flex;
    
    div{
         width:4rem;
        height:4rem;
       
    }
    img{
        width:100%;
        height: 100%;
        object-fit: cover;
       
    }

`
